        # Without 'exclusive', priority only orders evaluation; labels merge.
        rules = [
            {"pattern": "src/**", "labels": ["source"], "priority": 1},
            {"pattern": "src/api/**", "labels": ["api"], "priority": 5},
        ]
        self.assertEqual(
            assign_labels(["src/api/users.py"], rules), {"source", "api"}
        )


